 Here's a C++ program that generates the Fibonacci sequence using a recursive function, taking the first two sequence elements and the number of sequence elements to generate as user inputs:

```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n <= 0) throw invalid_argument("Number of sequence elements must be positive.");
    if (a < 0 || b < 0) throw invalid_argument("First two integers cannot be negative.");

    return (n <= 2) ? (n == 1 ? a : b) : fibonacci(n - 1, b, a + b);
}

int main() {
    int n, a, b;
    string input;

    cout << "Enter the first two integers of the Fibonacci sequence: ";
    getline(cin, input);
    istringstream iss(input);
    iss >> a;
    char separator;
    if (iss.fail()) {
        cerr << "Invalid input. Please enter the first integer." << endl;
        return 1;
    }
    iss.clear();
    iss.ignore(1); // consume comma
    iss >> b;
    if (iss.fail()) {
        cerr << "Invalid input. Please enter the second integer." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    getline(cin, input);
    iss.str(input);
    iss >> n;
    if (iss.fail()) {
        cerr << "Invalid input. Please enter a valid number." << endl;
        return 1;
    }

    try {
        cout << "Fibonacci sequence with " << n << " elements:" << endl;
        cout << fibonacci(n, a, b);
    } catch (const invalid_argument& e) {
        cerr << e.what() << endl;
        return 1;
    }

    return 0;
}
```

