1. First, let's create a simple C++ program using the Bubble Sort algorithm. This program will take an integer array as input and sort it in ascending order.

```cpp
#include <iostream>
#include <vector>

void bubbleSort(std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                std::swap(arr[j], arr[j + 1]);
            }
        }
    }
}

int main() {
    // Receive integer array from JSON input (To be implemented)

    std::vector<int> arr = {5, 2, 9, 1, 5, 6};
